set -Eeuo pipefail
sudo -n /usr/bin/python3 - <<'PY'
import os,subprocess,json
from pathlib import Path
src=Path('/srv/lowcost-europa')
parent=Path('/srv/projects')
dst=parent/'lowcost-europa'
def cmd(args,t=13):
 return subprocess.run(args,capture_output=True,text=True,timeout=t)
def isactive(s):
 return cmd(['systemctl','is-active',s+'.service'],9).stdout.strip()
def bots():
 r=cmd(['pm2','jlist'],14)
 if r.returncode:raise RuntimeError('PM2 offline')
 return {a.get('name'):(a.get('pm2_env') or {}).get('status') for a in json.loads(r.stdout)}
protected=['lowcost-europa','pink-iptv-backend','pink-vpn','fadego-staging','pm2-root','nginx','postgresql@16-main','ssh']
baseline={s:isactive(s) for s in protected}
if any(s!='active' for s in baseline.values()):raise RuntimeError('One protected service inactive before')
b0=bots()
if any(b0.get(x)!='online' for x in ('telegram-robot-leads','iptvpn_bot')):raise RuntimeError('Telegram apps unhealthy')
if not parent.is_dir() or parent.is_symlink() or not (parent/'iptvpn-bot').is_dir():raise RuntimeError('Canonical project root not established')
if not src.is_dir() or src.is_symlink() or dst.exists() or dst.is_symlink():raise RuntimeError('Source/destination not expected')
if src.stat().st_dev!=parent.stat().st_dev:raise RuntimeError('Cross-filesystem root move')
origin=cmd(['git','-C',str(src),'remote','get-url','origin'])
if origin.returncode or 'martaxi-boss/lowcost-europa' not in origin.stdout:raise RuntimeError('GitHub origin differs')
tracked=cmd(['git','-C',str(src),'status','--porcelain','--untracked-files=no'])
if tracked.returncode:raise RuntimeError('Git status unavailable')
d=cmd(['du','-x','-s','-B1',str(src)],45)
if d.returncode:raise RuntimeError('DU failed')
sz=int(d.stdout.split()[0])
inode=src.stat().st_ino
if not (src/'.venv/bin/python').exists():raise RuntimeError('Project venv not verified')
info=cmd(['systemctl','show','lowcost-europa.service','-p','MainPID','-p','WorkingDirectory','--no-pager'],12)
values=dict(line.split('=',1) for line in info.stdout.splitlines() if '=' in line)
pid=values.get('MainPID')
if info.returncode or values.get('WorkingDirectory')!=str(src) or not pid or pid=='0':raise RuntimeError('Live LowCost service not tied to expected root')
print('LOWCOST_OLD_PATH='+str(src))
print('LOWCOST_NEW_PHYSICAL_PATH='+str(dst))
print('APP_BYTES='+str(sz))
moved=False
try:
 src.rename(dst);moved=True
 src.symlink_to(dst,target_is_directory=True)
 if not src.is_symlink() or src.resolve()!=dst or dst.stat().st_ino!=inode:raise RuntimeError('Compatibility link or physical root mismatch')
 p=cmd([str(dst/'.venv/bin/python'),'-c','import sys; assert sys.version_info.major==3'],15)
 if p.returncode:raise RuntimeError('Python environment no longer starts')
 after=cmd(['git','-C',str(dst),'status','--porcelain','--untracked-files=no'],13)
 if after.returncode or after.stdout!=tracked.stdout:raise RuntimeError('Tracked project changed')
 s=cmd(['du','-x','-s','-B1',str(dst)],45)
 if s.returncode or int(s.stdout.split()[0])!=sz:raise RuntimeError('Directory size mismatch')
 info2=cmd(['systemctl','show','lowcost-europa.service','-p','MainPID','--no-pager'],10)
 if info2.returncode or ('MainPID='+pid) not in info2.stdout.splitlines():raise RuntimeError('LowCost process restarted')
 for name,old in baseline.items():
  if isactive(name)!=old:raise RuntimeError('Protected service changed state: '+name)
 b1=bots()
 for name in ('iptvpn_bot','telegram-robot-leads'):
  if b1.get(name)!='online':raise RuntimeError('Telegram bot stopped: '+name)
except Exception:
 if src.is_symlink() and src.resolve()==dst:src.unlink()
 if moved and dst.exists() and not src.exists():dst.rename(src)
 print('LOWCOST_MIGRATION_ROLLBACK=APPLIED')
 raise
print('CANONICAL_LOWCOST_PATH='+str(dst))
print('OLD_PATH_COMPAT_SYMLINK='+str(src))
print('SOURCE_PHYSICAL_MOVED=YES')
print('APP_BYTES_VERIFIED='+str(sz))
print('PYTHON_RUNTIME_TEST=PASS')
print('LOWCOST_PID_UNCHANGED='+str(pid))
print('GIT_TRACKED_CHANGES_PRESERVED=YES')
print('TELEGRAM_BOTS=ONLINE')
print('PROTECTED_SERVICES=ACTIVE')
print('DISK_SAVINGS_BYTES=0')
print('LOWCOST_CANONICAL_MOVE=PASS')
PY
